import { Suspense } from 'react';
import { HeroSlider } from '@/components/store/homepage/HeroSlider';
import { CategoryGrid } from '@/components/store/homepage/CategoryGrid';
import { FeaturedProducts } from '@/components/store/homepage/FeaturedProducts';
import { BestSellers } from '@/components/store/homepage/BestSellers';
import { PromoBanner } from '@/components/store/homepage/PromoBanner';
import { SocialProof } from '@/components/store/homepage/SocialProof';
import { BrandValues } from '@/components/store/homepage/BrandValues';
import { NewsletterSignup } from '@/components/store/homepage/NewsletterSignup';
import { getCategories, getProducts } from '@/services/product.service';

export const metadata = {
  title: 'ShareWardrobe - Modern Women\'s Fashion & Ethnic Wear',
  description: 'Discover the latest trends in women\'s fashion. Shop elegant dresses, timeless ethnic wear, jewelry, and accessories.',
};

// Data fetching components to enable streaming with Suspense
async function CategoriesSection() {
  try {
    const categories = await getCategories();
    return <CategoryGrid categories={categories} />;
  } catch (error) {
    console.error('Failed to load categories', error);
    return null; // Graceful fallback
  }
}

async function FeaturedSection() {
  try {
    const newArrivals = await getProducts({ 
      sort: 'newest', 
      limit: 8 
    });
    return <FeaturedProducts products={newArrivals} />;
  } catch (error) {
    console.error('Failed to load new arrivals', error);
    return null;
  }
}

async function TrendingSection() {
  try {
    // In a real app we might fetch by 'isFeatured=true' or top sales. 
    // Here we'll simulate by fetching top rated
    const bestSellers = await getProducts({ 
      sort: 'rating', 
      limit: 8 
    });
    return <BestSellers products={bestSellers} />;
  } catch (error) {
    console.error('Failed to load best sellers', error);
    return null;
  }
}

function SectionSkeleton({ height = "400px" }: { height?: string }) {
  return (
    <div 
      className="w-full bg-muted/20 animate-pulse my-12 max-w-7xl mx-auto px-4" 
      style={{ height }}
    />
  );
}

export default function HomePage() {
  return (
    <div className="flex flex-col min-h-screen bg-background">
      <HeroSlider />

      <Suspense fallback={<SectionSkeleton height="600px" />}>
        <CategoriesSection />
      </Suspense>

      <Suspense fallback={<SectionSkeleton height="500px" />}>
        <FeaturedSection />
      </Suspense>

      <PromoBanner />

      <Suspense fallback={<SectionSkeleton height="600px" />}>
        <TrendingSection />
      </Suspense>

      <SocialProof />

      <BrandValues />

      <NewsletterSignup />
    </div>
  );
}

"use client";

import { forwardRef, useState } from "react";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

export interface PhoneInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type"> {}

export const PhoneInput = forwardRef<HTMLInputElement, PhoneInputProps>(
  ({ className, onChange, value, ...props }, ref) => {
    // Basic formatting for BD numbers: +880 1XXX-XXXXXX
    const formatPhoneNumber = (val: string) => {
      // Strip all non-digits
      const digits = val.replace(/\D/g, "");
      
      // Auto-prefix 880 if user typed 01...
      let normalized = digits;
      if (normalized.startsWith("01")) {
        normalized = "880" + normalized.substring(1);
      }
      
      // Enforce max length of 13 digits (880 + 10 digits)
      normalized = normalized.slice(0, 13);
      
      return normalized;
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const formatted = formatPhoneNumber(e.target.value);
      // Create a synthetic event to pass down the formatted value
      const syntheticEvent = {
        ...e,
        target: {
          ...e.target,
          value: formatted,
          name: e.target.name
        }
      } as React.ChangeEvent<HTMLInputElement>;
      
      onChange?.(syntheticEvent);
    };

    // Display formatting
    let displayValue = value as string || "";
    if (displayValue.startsWith("880")) {
      const rest = displayValue.slice(3);
      if (rest.length > 4) {
        displayValue = `+880 ${rest.slice(0, 4)}-${rest.slice(4)}`;
      } else if (rest.length > 0) {
        displayValue = `+880 ${rest}`;
      } else {
        displayValue = "+880";
      }
    }

    return (
      <div className="relative">
        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground select-none pointer-events-none text-sm">
          🇧🇩
        </span>
        <Input
          type="tel"
          ref={ref}
          className={cn("pl-9 font-mono tracking-wide", className)}
          placeholder="+880 1XXX-XXXXXX"
          value={displayValue}
          onChange={handleChange}
          maxLength={15} // +880 XXXX-XXXXXX = 15 chars max
          {...props}
        />
      </div>
    );
  }
);
PhoneInput.displayName = "PhoneInput";

"use client";

import * as React from "react";
import {
  ColumnDef,
  ColumnFiltersState,
  SortingState,
  VisibilityState,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table";
import { ChevronDown, Search } from "lucide-react";

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  searchKey?: string;
  searchPlaceholder?: string;
}

export function DataTable<TData, TValue>({
  columns,
  data,
  searchKey,
  searchPlaceholder = "Search...",
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([]);
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>({});
  const [rowSelection, setRowSelection] = React.useState({});

  const table = useReactTable({
    data,
    columns,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
    },
  });

  return (
    <div className="w-full space-y-4">
      <div className="flex items-center justify-between">
        {searchKey && (
          <div className="flex items-center py-4 relative w-full max-w-sm">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder={searchPlaceholder}
              value={(table.getColumn(searchKey)?.getFilterValue() as string) ?? ""}
              onChange={(event) =>
                table.getColumn(searchKey)?.setFilterValue(event.target.value)
              }
              className="max-w-sm pl-9"
            />
          </div>
        )}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" className="ml-auto">
              Columns <ChevronDown className="ml-2 h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {table
              .getAllColumns()
              .filter((column) => column.getCanHide())
              .map((column) => {
                return (
                  <DropdownMenuCheckboxItem
                    key={column.id}
                    className="capitalize"
                    checked={column.getIsVisible()}
                    onCheckedChange={(value) =>
                      column.toggleVisibility(!!value)
                    }
                  >
                    {column.id}
                  </DropdownMenuCheckboxItem>
                );
              })}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      <div className="rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-24 text-center"
                >
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <div className="flex items-center justify-end space-x-2 py-4">
        <div className="flex-1 text-sm text-muted-foreground">
          {table.getFilteredSelectedRowModel().rows.length} of{" "}
          {table.getFilteredRowModel().rows.length} row(s) selected.
        </div>
        <div className="space-x-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            Previous
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useFormContext } from "react-hook-form";
import { FormControl, FormDescription, FormField as ShadcnFormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import React from "react";
import { type ControllerRenderProps } from "react-hook-form";

interface FormFieldProps {
  name: string;
  label?: string;
  description?: string;
  placeholder?: string;
  required?: boolean;
  className?: string;
  render: (props: { field: ControllerRenderProps<any, string> }) => React.ReactNode;
}

export function FormField({
  name,
  label,
  description,
  required,
  className,
  render,
}: FormFieldProps) {
  const { control } = useFormContext();

  return (
    <ShadcnFormField
      control={control}
      name={name}
      render={({ field }: { field: ControllerRenderProps<any, string> }) => (
        <FormItem className={className}>
          {label && (
            <FormLabel>
              {label}
              {required && <span className="text-destructive ml-1">*</span>}
            </FormLabel>
          )}
          <FormControl>{render({ field })}</FormControl>
          {description && <FormDescription>{description}</FormDescription>}
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

